 public static bool B(Dictionary<string,object> x,string k){return x.ContainsKey(k)&&Convert.ToBoolean(x[k]);}
 public static int N(Dictionary<string,object> x,string k){return Convert.ToInt32(x[k]);}
 public static string Recognize(List<Point> pts,int min,int tolerance){if(pts.Count<2)return "";Point anchor=pts[0];string s="";bool uncertain=false;foreach(var p in pts.GetRange(1,pts.Count-1)){double x=p.X-anchor.X,y=p.Y-anchor.Y;if(Math.Sqrt((double)x*x+(double)y*y)<min)continue;double a=Math.Atan2(y,x)*180/Math.PI;string d=Math.Abs(a)<=tolerance?"R":Math.Abs(a-90)<=tolerance?"D":Math.Abs(a+90)<=tolerance?"U":Math.Abs(Math.Abs(a)-180)<=tolerance?"L":"";if(d==""){uncertain=true;continue;}uncertain=false;if(!s.EndsWith(d))s+=d;if(s.Length>4)return "";anchor=p;}return uncertain?"":s;}
 public static int WheelHit(int x,int y,int radius,int center,int innerCount,bool second,int secondCount,bool bounded,bool outside=false,int outsideCount=1,bool singleOutside=true){double distance=Math.Sqrt((double)x*x+(double)y*y);if(distance<=center)return -1;if(distance>radius)return outside?innerCount+(second?secondCount:0)+(singleOutside?0:Hit(x,y,outsideCount,center)):-1;bool ring2=second&&distance>=center+(radius-center)*.5;int index=Hit(x,y,ring2?secondCount:innerCount,center);return ring2?innerCount+index:index;}
