 }
 }catch(Exception ex){Cancel();Emit("error",ex.Message);}return Native.CallNextHookEx(hook,code,wp,lp);}
 double PointSpan(){int left=start.X,right=start.X,top=start.Y,bottom=start.Y;foreach(var p in points){left=Math.Min(left,p.X);right=Math.Max(right,p.X);top=Math.Min(top,p.Y);bottom=Math.Max(bottom,p.Y);}return Math.Max(right-left,bottom-top);}
