 string SelectedAction(){if(selected<0)return "";int count=Data.N(wheel,"count");if(selected<count)return Convert.ToString(Data.Arr(wheel["slots"])[selected]);int second=Data.B(wheel,"secondEnabled")?Data.N(wheel,"secondCount"):0;if(selected<count+second)return Convert.ToString(Data.Arr(wheel["secondSlots"])[selected-count]);if(!Data.B(wheel,"outsideEnabled"))return "";return Data.S(wheel,"outsideMode")=="single"?Data.S(wheel,"outsideActionId"):Convert.ToString(Data.Arr(wheel["outsideSlots"])[selected-count-second]);}
