 void Execute(){var a=Action(pendingAction);string type=a==null?"":Data.S(a,"type");try{if(a==null)throw new Exception("动作已不存在");if(dryRun){Cancel();Emit("dry-run",Data.S(a,"id"));return;}if(type=="key"||type=="text"){uint pid;if(!Native.IsWindow(target))throw new Exception("目标窗口已关闭");Native.GetWindowThreadProcessId(target,out pid);if(pid!=targetPid)throw new Exception("目标窗口已改变");if(Native.GetForegroundWindow()!=target)throw new Exception("目标焦点已改变，动作取消");Native.SetForegroundWindow(target);if(Native.GetForegroundWindow()!=target)throw new Exception("无法恢复目标焦点");}
 string value=Data.S(a,"value");if(type=="key")Hotkey(value);else if(type=="text")UnicodeText(value);else if(type=="url"){Uri uri;if(!Uri.TryCreate(value,UriKind.Absolute,out uri)||(uri.Scheme!="https"&&uri.Scheme!="http"))throw new Exception("网址无效");Process.Start(new ProcessStartInfo(value){UseShellExecute=true});}else if(type=="path")Process.Start(new ProcessStartInfo(value){UseShellExecute=true});else if(type=="app"){string args="";if(a.ContainsKey("args"))foreach(var arg in Data.Arr(a["args"]))args+=Quote(Convert.ToString(arg))+" ";Process.Start(new ProcessStartInfo(value,args){UseShellExecute=false,WorkingDirectory=Data.S(a,"cwd",System.IO.Path.GetDirectoryName(value))});}Cancel();if(actionFromGesture)overlay.Submit(new RenderFrame{Kind="feedback",Cursor=current,Dpi=dpi,Hint="已执行："+Data.S(a,"name")});Emit("executed","已执行："+Data.S(a,"name"));}catch(Exception ex){Cancel();if(actionFromGesture)overlay.Submit(new RenderFrame{Kind="feedback",Cursor=current,Dpi=dpi,Hint="执行失败："+ex.Message});Emit("error",ex.Message);}}
 static string Quote(string value){var b=new StringBuilder("\"");int slashes=0;foreach(char c in value){if(c=='\\'){slashes++;continue;}if(c=='\"'){b.Append('\\',slashes*2+1);b.Append(c);}else{b.Append('\\',slashes);b.Append(c);}slashes=0;}b.Append('\\',slashes*2);b.Append('"');return b.ToString();}
 static ushort Vk(string s){s=s.ToUpperInvariant();if(s=="CTRL")return 17;if(s=="ALT")return 18;if(s=="SHIFT")return 16;if(s=="WIN")return 91;if(s.Length==1)return (ushort)s[0];int n;if(s.StartsWith("F")&&int.TryParse(s.Substring(1),out n)&&n>=1&&n<=24)return (ushort)(111+n);var map=new Dictionary<string,ushort>{{"LEFT",37},{"RIGHT",39},{"UP",38},{"DOWN",40},{"ENTER",13},{"TAB",9},{"SPACE",32},{"BACKSPACE",8},{"DELETE",46},{"HOME",36},{"END",35},{"PAGEUP",33},{"PAGEDOWN",34},{"ESCAPE",27}};return map[s];}
 static void Hotkey(string value){var pressed=new List<ushort>();try{foreach(string key in value.Split('+')){ushort vk=Vk(key);Native.Key(vk,false);pressed.Add(vk);}}finally{pressed.Reverse();foreach(var vk in pressed)Native.Key(vk,true);}}
 static void UnicodeText(string value){foreach(char c in value){if(c=='\r')continue;if(c=='\n'){Native.Key(13,false);Native.Key(13,true);continue;}var a=new Native.Input();a.type=1;a.u.ki=new Native.KI{scan=c,flags=4,extra=Native.Marker};var b=a;b.u.ki.flags=6;Native.Send(new Native.Input[]{a,b});}}
 protected override void ExitThreadCore(){timer.Stop();Native.UnhookWindowsHookEx(hook);overlay.Dispose();dispatcher.Dispose();base.ExitThreadCore();}
}

